const input = $json.body ?? $json;
const now = new Date();
const requestId = String(input.request_id ?? input.event_id ?? `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
const correlationId = `COR-${now.toISOString().slice(0, 10).replaceAll('-', '')}-${requestId.replace(/[^a-zA-Z0-9]/g, '').slice(-8)}`;

const name = String(input.name ?? input.full_name ?? '').trim().replace(/\s+/g, ' ');
const email = String(input.email ?? '').trim().toLowerCase();
const phone = String(input.phone ?? '').trim();
const position = String(input.position ?? input.job_position ?? '').trim();
const experience = input.experience_years === undefined || input.experience_years === null || input.experience_years === '' ? null : Number(input.experience_years);
const skills = Array.isArray(input.skills) ? input.skills.map((skill) => String(skill).trim()).filter(Boolean) : String(input.skills ?? '').split(',').map((skill) => skill.trim()).filter(Boolean);
const expectedSalary = input.expected_salary === undefined || input.expected_salary === null || input.expected_salary === '' ? null : Number(input.expected_salary);
const joiningDate = input.joining_date ? String(input.joining_date).slice(0, 10) : null;
const cvUrl = input.cv_url ?? input.cv_link ?? null;
const cvPresent = Boolean(input.cv_present || cvUrl || input.cv_text);

const errors = [];
if (!name) errors.push('Name is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('A valid email is required');
if (!/^\+?[0-9()\-\s]{7,20}$/.test(phone)) errors.push('A valid phone number is required');
if (!['Python Developer', 'Business Development Executive', 'QA Engineer'].includes(position)) errors.push('Position is not supported');
if (experience === null || Number.isNaN(experience) || experience < 0 || experience > 60) errors.push('Experience must be between 0 and 60 years');
if (expectedSalary === null || Number.isNaN(expectedSalary) || expectedSalary < 0) errors.push('Expected salary must be a non-negative number');
if (!joiningDate || Number.isNaN(Date.parse(joiningDate))) errors.push('A valid joining date is required');
if (!cvPresent) errors.push('CV or CV link is required');

const normalized = {
  correlation_id: correlationId,
  event_id: `APPLICATION_EVENT_${requestId}`,
  candidate_id: null,
  name,
  email,
  phone,
  position,
  experience_years: experience,
  skills,
  expected_salary: expectedSalary,
  currency: String(input.currency ?? 'PKR').toUpperCase(),
  joining_date: joiningDate,
  cv_url: cvUrl,
  cv_present: cvPresent,
  status: errors.length ? 'MANUAL_REVIEW' : 'VALIDATED',
  validation_errors: errors,
  received_at: now.toISOString(),
  source: String(input.source ?? 'webhook')
};

return [{ json: { ...normalized, is_valid: errors.length === 0, manual_review_required: errors.length > 0 } }];
